INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'AI-агенти', 'AI Agents', 'ai-agents' FROM `categories` c WHERE c.`slug` = 'tools-automation' LIMIT 1;

