-- Manus — AI-агенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'manus.im' OR LOWER(`name`) = LOWER('Manus'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Manus', NULL, 'https://manus.im', NULL, NULL, 'Автономний AI-агент, який сам виконує багатокрокові завдання: глибоке дослідження теми, створення сайтів і презентацій, робота в браузері — від запиту до готового результату.', 'An autonomous AI agent that carries out multi-step tasks on its own: in-depth research, building websites and slide decks, working in the browser — from a request to a finished result.', 'Manus — універсальний AI-агент, якому дають завдання, а не окремі запитання. Він сам планує кроки, шукає інформацію, працює з браузером і файлами та повертає готовий результат: аналітичний звіт, сайт, презентацію, зображення чи відео. Режим Wide Research розподіляє велике дослідження між багатьма паралельними підзадачами. Можна запускати до 20 завдань одночасно й планувати завдання за розкладом. Працює у вебі, як настільний і мобільний застосунок, а також як розширення браузера. Оплата — за кредити: платні тарифи коштують $20, $40 і $200 на місяць (4 000, 8 000 і 40 000 кредитів), щодня додаються 300 кредитів; річна оплата дешевша на 17%.', 'Manus is a general-purpose AI agent that you give tasks rather than individual questions. It plans the steps itself, searches for information, works with the browser and files, and returns a finished result: an analytical report, a website, a slide deck, an image or a video. Wide Research mode splits a large research job into many parallel sub-tasks. You can run up to 20 tasks at once and schedule tasks. It works on the web, as a desktop and mobile app, and as a browser extension. Usage is paid in credits: paid plans cost $20, $40 and $200 a month (4,000, 8,000 and 40,000 credits), with 300 refresh credits added daily; annual billing is 17% cheaper.', 'Виконання багатокрокових завдань від запиту до результату
Wide Research — паралельне глибоке дослідження
Створення сайтів, презентацій, зображень і відео
До 20 одночасних і запланованих завдань
Веб, настільний і мобільний застосунки, розширення браузера', 'Multi-step tasks from request to finished result
Wide Research — parallel in-depth research
Builds websites, slide decks, images and video
Up to 20 concurrent and scheduled tasks
Web, desktop and mobile apps, browser extension', 'Аналітики, маркетологи, підприємці й усі, хто хоче доручати AI цілі завдання, а не лише ставити запитання.', 'Analysts, marketers, entrepreneurs and anyone who wants to hand whole tasks to AI rather than just ask questions.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'manus.im' OR LOWER(`name`) = LOWER('Manus')) ORDER BY `id` LIMIT 1);
