INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Manus is a general-purpose AI agent that you give tasks rather than individual questions. It plans the steps itself, searches for information, works with the browser and files, and returns a finished result: an analytical report, a website, a slide deck, an image or a video. Wide Research mode splits a large research job into many parallel sub-tasks. You can run up to 20 tasks at once and schedule tasks. It works on the web, as a desktop and mobile app, and as a browser extension. Usage is paid in credits: paid plans cost $20, $40 and $200 a month (4,000, 8,000 and 40,000 credits), with 300 refresh credits added daily; annual billing is 17% cheaper.', 'manual' FROM DUAL WHERE @new = 1;
