-- Genspark — AI-агенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'genspark.ai' OR LOWER(`name`) = LOWER('Genspark'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Genspark', NULL, 'https://www.genspark.ai', NULL, NULL, 'AI-робочий простір із «супер-агентом»: за одним запитом готує презентації, таблиці, документи й дослідження, використовуючи провідні моделі GPT, Claude і Gemini.', 'An AI workspace with a ''super agent'': from a single request it prepares slide decks, spreadsheets, documents and research using leading GPT, Claude and Gemini models.', 'Genspark — AI-робочий простір, побудований довкола супер-агента, який сам обирає інструменти й моделі під завдання. Він уміє готувати AI-презентації та AI-таблиці, писати документи, проводити глибоке дослідження з джерелами, генерувати зображення й відео та працювати з файлами в AI Drive. В одній підписці доступні провідні моделі — GPT, Claude, Gemini та інші. Є безкоштовний доступ з обмеженнями; платні тарифи: Plus — $24,99 на місяць (10 000 кредитів) і Pro — $249,99 на місяць (125 000 кредитів), при річній оплаті дешевше. Для компаній є окремі бізнес-тарифи.', 'Genspark is an AI workspace built around a super agent that picks the right tools and models for each task. It can produce AI slides and AI sheets, write documents, run in-depth research with sources, generate images and video, and work with files in AI Drive. Leading models — GPT, Claude, Gemini and others — are available in one subscription. There is limited free access; paid plans are Plus at $24.99 a month (10,000 credits) and Pro at $249.99 a month (125,000 credits), cheaper with annual billing. Separate business plans are available for companies.', 'Супер-агент сам обирає інструменти й моделі
AI-презентації, AI-таблиці та документи
Глибоке дослідження з джерелами
GPT, Claude і Gemini в одній підписці
Сховище файлів AI Drive', 'Super agent picks tools and models itself
AI slides, AI sheets and documents
In-depth research with sources
GPT, Claude and Gemini in one subscription
AI Drive file storage', 'Офісні працівники, аналітики й підприємці, яким потрібні готові презентації, таблиці й звіти без ручної роботи.', 'Office workers, analysts and entrepreneurs who need ready slides, spreadsheets and reports without manual work.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
