-- Relevance AI — AI-агенти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'relevanceai.com' OR LOWER(`name`) = LOWER('Relevance AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Relevance AI', NULL, 'https://relevanceai.com', NULL, NULL, 'Платформа для побудови «AI-команди» компанії: агенти для продажів, підтримки й операцій, що працюють з 2 000+ інтеграціями, дзвонять і ведуть зустрічі.', 'A platform for building a company''s ''AI workforce'': agents for sales, support and operations that work with 2,000+ integrations and can make calls and join meetings.', 'Relevance AI допомагає компаніям створювати AI-агентів, які беруть на себе рутинні процеси — від кваліфікації лідів і досліджень для продажів до обробки звернень і внутрішніх операцій. Агентам задають інструкції, підключають інструменти та дані, а далі вони працюють самостійно або в зв''язці з іншими агентами. Платформа має понад 2 000 інтеграцій, агентів для дзвінків і зустрічей, керування доступами (SSO, ролі) та необмежену кількість агентів, інструментів і користувачів у корпоративному тарифі. Ціни на сайті не опубліковано — тариф Enterprise узгоджується з відділом продажів.', 'Relevance AI helps companies build AI agents that take over routine processes — from lead qualification and sales research to handling requests and internal operations. You give agents instructions, connect tools and data, and they then work on their own or alongside other agents. The platform offers 2,000+ integrations, calling and meeting agents, access management (SSO, roles) and unlimited agents, tools and users on the enterprise plan. Pricing is not published on the website — the Enterprise plan is agreed with sales.', 'Конструктор AI-агентів без програмування
Понад 2 000 інтеграцій
Агенти для дзвінків і зустрічей
SSO та рольовий доступ', 'No-code AI agent builder
2,000+ integrations
Calling and meeting agents
SSO and role-based access', 'Відділи продажів, підтримки й операцій у компаніях, які хочуть автоматизувати процеси AI-агентами.', 'Sales, support and operations teams in companies that want to automate processes with AI agents.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
