INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Dust', NULL, 'https://dust.tt', NULL, NULL, 'Платформа корпоративних AI-агентів, підключених до даних компанії — Slack, Notion, GitHub та інших; агентів створюють самі співробітники, без розробників.', 'A platform for company AI agents connected to company data — Slack, Notion, GitHub and more; employees build agents themselves, without developers.', 'Dust дає командам змогу створювати власних AI-агентів, які мають доступ до знань компанії: документів, переписки, задач і коду з Slack, Notion, GitHub та інших сервісів. Агенти відповідають на запитання з посиланнями на джерела, готують звіти, допомагають підтримці й продажам і можуть працювати в зв''язці. Доступно понад 20 моделей. Тарифи — за користувача: Free (500 кредитів), Pro — €30 на місяць (€24 при річній оплаті, 8 000 кредитів), Max — €150 на місяць (€120 при річній оплаті, 40 000 кредитів); Enterprise — за запитом, з розгортанням в окремому середовищі.', 'Dust lets teams build their own AI agents with access to company knowledge: documents, conversations, tasks and code from Slack, Notion, GitHub and other services. Agents answer questions with links to sources, prepare reports, help support and sales teams and can work together. More than 20 models are available. Plans are per user: Free (500 credits), Pro at €30 a month (€24 billed yearly, 8,000 credits) and Max at €150 a month (€120 billed yearly, 40,000 credits); Enterprise is on request, with single-tenant deployment.', 'Агенти з доступом до даних компанії
Інтеграції зі Slack, Notion, GitHub та ін.
Понад 20 моделей
Відповіді з посиланнями на джерела', 'Agents with access to company data
Slack, Notion, GitHub and other integrations
20+ models
Answers with links to sources', 'Компанії, які хочуть дати кожному співробітнику агентів, що знають внутрішні документи й процеси.', 'Companies that want every employee to have agents that know internal documents and processes.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
