INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Devin', NULL, 'https://devin.ai', NULL, NULL, 'AI-інженер-програміст від Cognition: агенти самостійно пишуть, тестують і виправляють код у хмарі, а розробник ставить завдання й перевіряє результат.', 'An AI software engineer from Cognition: agents write, test and fix code on their own in the cloud, while the developer sets tasks and reviews the result.', 'Devin — AI-агент для розробки програмного забезпечення від компанії Cognition. Йому можна доручити завдання — виправити баг, додати функцію, провести рефакторинг чи міграцію, — і він сам вивчає репозиторій, пише код, запускає тести й готує зміни на перевірку. Хмарні агенти працюють паралельно, тож кілька завдань можна вести одночасно. Тарифи: Free — обмежена квота; Pro — $20 на місяць; Max — $200 на місяць зі значно більшими квотами; Team — $80 на місяць плюс $40 за кожного розробника (до 200 користувачів); Enterprise — за запитом, з SSO та розгортанням у VPC.', 'Devin is an AI agent for software development from Cognition. You can hand it a task — fix a bug, add a feature, refactor or migrate code — and it studies the repository, writes the code, runs tests and prepares changes for review. Cloud agents run in parallel, so several tasks can be handled at once. Plans: Free with a light quota; Pro at $20 a month; Max at $200 a month with much higher quotas; Team at $80 a month plus $40 per developer (up to 200 users); Enterprise on request, with SSO and VPC deployment.', 'Самостійне виконання завдань у репозиторії
Написання коду, тести й підготовка змін на перевірку
Паралельні хмарні агенти
Командний тариф з панеллю адміністратора', 'Completes tasks in the repository on its own
Writes code, runs tests and prepares changes for review
Parallel cloud agents
Team plan with an admin dashboard', 'Розробники та інженерні команди, які хочуть делегувати AI рутинні задачі з коду.', 'Developers and engineering teams that want to delegate routine coding tasks to AI.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'devin.ai' OR LOWER(`name`) = LOWER('Devin')) ORDER BY `id` LIMIT 1);
